import hashlib, json, os, pathlib
artifacts = [{"name": p.name, "digest": {"sha256": hashlib.sha256(p.read_bytes()).hexdigest()}} for p in pathlib.Path("dist").glob("*.AppImage")]
statement = {"_type": "https://in-toto.io/Statement/v1", "subject": artifacts, "predicateType": "https://slsa.dev/provenance/v1", "predicate": {"buildDefinition": {"buildType": "https://github.com/ItsAnunesS/elo-talks/appimage/v1", "externalParameters": {"repository": os.environ["GITHUB_REPOSITORY"], "ref": os.environ["GITHUB_REF"]}, "resolvedDependencies": [{"uri": "git+https://github.com/"+os.environ["GITHUB_REPOSITORY"], "digest": {"gitCommit": os.environ["GITHUB_SHA"]}}]}, "runDetails": {"builder": {"id": "https://github.com/"+os.environ["GITHUB_REPOSITORY"]+"/.github/workflows/release.yml@refs/heads/release"}, "metadata": {"invocationId": "https://github.com/"+os.environ["GITHUB_REPOSITORY"]+"/actions/runs/"+os.environ["GITHUB_RUN_ID"]}}}}
pathlib.Path("dist/provenance.json").write_text(json.dumps(statement, indent=2)+"\n")
